-- Seed data for `hosts`
INSERT INTO `hosts` (`id`, `name`, `role`,`bio`, `avatar`) VALUES
(1, 'Sofia Rossi','歷史導覽員','羅馬在地導覽員，熟悉古城巷弄與義式咖啡文化。', '/images/experiences/avatars/host-sofia.jpg'),
(2, 'Lukas Weber','歷史導覽員', '慕尼黑料理老師，擅長巴伐利亞家常菜與啤酒文化。', '/images/experiences/avatars/host-lukas.jpg'),
(3, 'Claire Dubois','歷史導覽員', '巴黎藝術史研究者，帶旅人用輕鬆方式看懂博物館。', '/images/experiences/avatars/host-claire.jpg'),
(4, 'Anna Novak','歷史導覽員', '布拉格戶外嚮導，喜歡分享河岸步道與城市傳說。', '/images/experiences/avatars/host-anna.jpg'),
(5, 'Marco Bianchi','歷史導覽員', '佛羅倫斯歷史導覽員，專長文藝復興建築與街區故事。', '/images/experiences/avatars/host-marco.jpg'),
(6, 'Elena Garcia','歷史導覽員', '西班牙品酒師，熟悉里奧哈葡萄酒與小酒館文化。', '/images/experiences/avatars/host-elena.jpg'),
(7, 'Ingrid Hansen','歷史導覽員', '哥本哈根陶藝職人，開設小班制手作體驗。', '/images/experiences/avatars/host-ingrid.jpg'),
(8, 'Mateo Alvarez','歷史導覽員', '巴塞隆納吉他手，長期參與佛朗明哥演出。', '/images/experiences/avatars/host-mateo.jpg'),
(9, 'Emma Clarke','歷史導覽員', '倫敦旅拍攝影師，擅長自然光人像與街景構圖。', '/images/experiences/avatars/host-emma.jpg'),
(10, 'Nora Schneider','歷史導覽員', '維也納親子活動規劃師，設計適合家庭的文化路線。', '/images/experiences/avatars/host-nora.jpg');

-- --------------------------------------------------------
-- Seed data for `experiences`
-- 100 experiences; images and sessions use IDs 1 to 100

INSERT INTO `experiences` (`id`, `category_id`, `host_id`, `title`, `description`, `meeting_point`, `city`, `longitude`, `latitude`, `created_at`) VALUES
(1, 5, 1, '倫敦經典街景自然光旅拍', '由專業攝影師帶領，在倫敦經典街區捕捉自然生動的人像。走訪大笨鐘、紅色電話亭與泰晤士河畔等代表性場景。攝影師會提供簡單易懂的姿勢與取景指導，即使第一次拍攝也能自在入鏡。行程結束後將獲得精選調色照片，留下專屬於你的倫敦旅行回憶。', 'Westminster Station 1 號出口', '倫敦', -0.124625, 51.500729, '2026-07-13 12:05:00'),
(2, 2, 2, '羅浮宮經典藝術深度導覽之旅', '由專業藝文導覽員帶領，認識羅浮宮重要館藏與建築歷史。精選蒙娜麗莎、米洛的維納斯與勝利女神等經典作品進行解說。透過作品背後的時代故事與創作細節，輕鬆理解西方藝術發展。適合第一次造訪羅浮宮的旅客，在有限時間內掌握最具代表性的藝術精華。', '羅浮宮玻璃金字塔入口附近', '巴黎', 2.337644, 48.860611, '2026-07-13 12:10:00'),
(3, 3, 3, '法餐私廚經典料理品味之夜', '走進巴黎私廚餐桌，品嚐以當季食材設計的經典法式料理。由主廚介紹每道菜的烹調方式、食材來源與法國飲食文化。餐點包含前菜、主餐及甜點，並搭配適合的葡萄酒或無酒精飲品。透過小班制用餐與主廚交流，在自在氛圍中感受巴黎人的精緻生活。', '巴黎瑪黑區聖保羅地鐵站出口', '巴黎', 2.360137, 48.855281, '2026-07-13 12:15:00'),
(4, 4, 4, '腳踏車市區深度探索漫遊之旅', '騎乘舒適的城市腳踏車，跟著在地嚮導探索阿姆斯特丹的大街小巷。沿途經過運河、特色橋梁與充滿生活感的社區。導覽員將分享城市發展、自行車文化與居民的日常故事。行程步調輕鬆並安排多次停留，適合具備基本騎乘能力的旅客。', '阿姆斯特丹中央車站正門廣場', '阿姆斯特丹', 4.900272, 52.379189, '2026-07-13 12:20:00'),
(5, 1, 5, '聖家堂建築藝術古蹟深度導覽', '由專業導覽員帶領，深入認識聖家堂的建築構造與歷史背景。欣賞高第運用自然光線、幾何圖形與宗教意象打造的空間。透過立面雕刻與教堂內部細節，了解不同時期的設計故事。適合喜愛建築與文化的旅客，完整感受巴賽隆納最具代表性的地標。', '聖家堂誕生立面入口附近', '巴賽隆納', 2.174355, 41.403629, '2026-07-13 12:25:00'),
(6, 6, 6, '瘋馬秀巴黎華麗夜間表演體驗', '走進巴黎知名的瘋馬秀劇場，欣賞融合舞蹈、燈光與舞台藝術的精彩演出。表演以精準編舞和視覺效果呈現充滿法式風格的夜間娛樂。舒適的劇院環境讓旅客能近距離感受專業舞者的舞台魅力。適合安排在巴黎夜遊行程中，體驗不同於白天觀光的城市氣氛。', 'Crazy Horse Paris 劇場入口', '巴黎', 2.301132, 48.865925, '2026-07-13 12:30:00'),
(7, 6, 7, '悲慘世界音樂劇經典劇院之夜', '走進倫敦西區劇院，欣賞改編自經典文學作品的悲慘世界音樂劇。透過氣勢磅礴的歌曲、細膩演技與舞台設計感受劇情張力。演出呈現愛、犧牲與希望等動人主題，即使初次接觸音樂劇也能投入其中。適合喜愛表演藝術的旅客，體驗倫敦夜晚最具代表性的文化活動。', 'Sondheim Theatre 正門入口', '倫敦', -0.131286, 51.511099, '2026-07-13 12:35:00'),
(8, 4, 8, '貢多拉遊船水都浪漫探索之旅', '搭乘威尼斯傳統貢多拉，沿著蜿蜒水道欣賞水都特有的城市景觀。船夫將帶領旅客穿過小運河、古老石橋與歷史建築之間。從水面角度觀察威尼斯的生活細節，感受與步行觀光不同的旅行節奏。適合情侶、家人與初次造訪的旅客，留下浪漫而經典的水都回憶。', '聖馬可廣場鐘樓附近', '威尼斯', 12.338176, 45.434035, '2026-07-13 12:40:00'),
(9, 6, 9, '啤酒節慕尼黑經典狂歡之夜', '走進慕尼黑熱鬧的啤酒節會場，感受巴伐利亞最具代表性的節慶氣氛。品嚐當地啤酒與傳統料理，並認識不同酒款及飲食文化。現場樂隊、民族服飾與大型帳篷共同營造歡樂的夜間體驗。由熟悉會場的帶隊人員協助安排動線，讓旅客安心參與這場城市盛會。', 'Theresienwiese 地鐵站出口', '慕尼黑', 11.549143, 48.131929, '2026-07-13 12:45:00'),
(10, 6, 10, '紅磨坊歌舞盛宴璀璨巴黎之夜', '走進巴黎蒙馬特的紅磨坊劇場，欣賞充滿華麗服裝與舞台效果的歌舞演出。專業舞者以經典康康舞、音樂與燈光呈現法式夜生活魅力。劇院歷史悠久且氣氛熱鬧，讓旅客感受巴黎娛樂文化的代表性場景。適合安排為旅行中的特別夜晚，在璀璨演出中留下難忘回憶。', 'Moulin Rouge 劇場正門入口', '巴黎', 2.332260, 48.884139, '2026-07-13 12:50:00'),
(11, 5, 1, '倫敦塔橋晨光人像寫真旅拍', '在清晨柔和光線下拍攝倫敦塔橋與泰晤士河畔景色。攝影師會協助引導自然姿勢與適合你的拍照角度。行程包含橋邊街景與具有倫敦特色的建築背景。結束後將提供精選修圖照片，留下專屬倫敦回憶。', 'Tower Bridge 正門', '倫敦', -0.075400, 51.505500, '2026-07-21 18:43:34'),
(12, 2, 2, '巴黎羅浮宮藝術名作深度導覽', '由導覽員帶領認識羅浮宮最具代表性的館藏與故事。用容易理解的方式欣賞蒙娜麗莎與古典人體藝術作品。行程也會分享建築改建與宮殿歷史留下的重要痕跡。適合第一次參觀羅浮宮又想深入了解藝術的旅人。', 'Musée du Louvre 金字塔入口', '巴黎', 2.336400, 48.860600, '2026-07-21 18:43:34'),
(13, 6, 3, '慕尼黑啤酒花園微醺夜遊體驗', '走進慕尼黑當地人喜愛的傳統啤酒花園感受夜晚氣氛。認識不同德國啤酒風味與巴伐利亞飲酒文化特色。品嚐經典香腸、椒鹽捲餅與適合搭配的在地小食。適合想輕鬆認識慕尼黑夜生活的成年旅人。', 'Marienplatz 新市政廳前', '慕尼黑', 11.575500, 48.137400, '2026-07-21 18:43:34'),
(14, 1, 4, '阿姆斯特丹王宮歷史文化導覽', '從水壩廣場出發認識阿姆斯特丹王宮與城市發展故事。導覽員會介紹荷蘭黃金時代留下的重要建築與文化。沿途欣賞老城街道、運河景觀和具有特色的山形屋。適合喜歡歐洲歷史建築與城市文化的旅人。', 'Dam Square 水壩廣場', '阿姆斯特丹', 4.891000, 52.373100, '2026-07-21 18:43:34'),
(15, 1, 5, '威尼斯聖馬可廣場古蹟巡禮', '走訪聖馬可廣場周邊的重要建築與威尼斯共和國歷史。認識聖馬可大教堂、鐘樓和總督宮背後的城市故事。導覽員會分享威尼斯商業繁盛時期留下的文化痕跡。適合第一次造訪威尼斯並想掌握必看景點的旅人。', 'Piazza San Marco 廣場入口', '威尼斯', 12.337000, 45.434000, '2026-07-21 18:43:34'),
(16, 3, 6, '巴賽隆納海鮮燉飯料理體驗', '跟著主廚前往市場挑選當季海鮮與西班牙特色食材。學習製作香氣濃郁的傳統海鮮燉飯與經典小菜。課程會介紹橄欖油、香料和高湯對風味的重要影響。完成後能和同行旅人一起享用親手製作的料理。', 'Mercat de la Boqueria 正門', '巴賽隆納', 2.171800, 41.382600, '2026-07-21 18:43:34'),
(17, 4, 7, '倫敦泰晤士河畔健走探索', '沿著泰晤士河步行欣賞倫敦眼、大笨鐘與河岸風景。導覽員會分享河畔地標與倫敦城市發展的有趣故事。路線安排平緩好走，也會保留時間讓旅人拍照休息。適合喜歡輕鬆散步並認識倫敦經典景點的旅人。', 'London Eye 入口前', '倫敦', -0.119500, 51.503300, '2026-07-21 18:43:34'),
(18, 3, 8, '巴黎左岸法式私廚饗宴體驗', '在巴黎左岸溫馨私廚中品嚐道地法式家常料理。主廚會介紹每道菜的食材來源與傳統烹調方式。餐點搭配當季甜點與適合佐餐的法國飲品選擇。適合想用一頓晚餐深入感受巴黎生活風格的旅人。', 'Saint-Germain-des-Prés 地鐵站出口', '巴黎', 2.333300, 48.853800, '2026-07-21 18:43:34'),
(19, 2, 9, '慕尼黑當代藝術美術館導覽', '走進慕尼黑現代藝術空間認識歐洲當代創作的特色。導覽員會用淺顯方式說明作品背後的概念與時代背景。行程包含建築特色、重要展品和藝術家的創作故事。適合想輕鬆接觸當代藝術又不想自己查資料的旅人。', 'Pinakothek der Moderne 正門', '慕尼黑', 11.573700, 48.148400, '2026-07-21 18:43:34'),
(20, 4, 10, '阿姆斯特丹運河單車探索之旅', '騎乘單車穿梭阿姆斯特丹經典運河與安靜住宅街區。沿途停靠特色橋梁、花市與當地人才知道的小景點。導覽員會分享荷蘭單車文化和城市規劃的生活故事。路線平緩好騎，適合想以自在步調認識城市的旅人。', 'Amsterdam Centraal Station 前廣場', '阿姆斯特丹', 4.900300, 52.379100, '2026-07-21 18:43:34'),
(21, 1, 1, '威尼斯總督宮歷史文化導覽', '走進總督宮認識威尼斯共和國最輝煌時期的政治與藝術歷史。導覽員會介紹議事廳、華麗壁畫和宮殿建築細節。行程也會分享總督宮與聖馬可廣場的重要故事。適合喜歡歐洲歷史與古典建築的旅人。', 'Palazzo Ducale 正門', '威尼斯', 12.340800, 45.433700, '2026-07-21 19:30:58'),
(22, 2, 2, '威尼斯玻璃工藝藝術導覽體驗', '前往充滿工藝氣息的玻璃工坊認識威尼斯傳統製作技術。了解玻璃工匠如何利用高溫塑造出細緻的藝術作品。現場可欣賞不同色彩與造型背後代表的設計巧思。適合喜歡手作藝術和特色紀念品的旅人。', 'Fondamenta Nove 碼頭', '威尼斯', 12.347600, 45.444600, '2026-07-21 19:30:58'),
(23, 5, 3, '威尼斯運河人像旅拍寫真體驗', '由在地攝影師帶你走進威尼斯運河旁的特色巷弄取景。拍攝過程會引導自然姿勢，讓不常拍照的人也能放鬆。行程包含經典橋景、水道與充滿電影感的街道背景。結束後提供精選照片，留下專屬威尼斯回憶。', 'Rialto Bridge 橋頭', '威尼斯', 12.335800, 45.438000, '2026-07-21 19:30:58'),
(24, 1, 4, '巴賽隆納哥德區古蹟巡禮導覽', '漫步巴賽隆納哥德區，認識中世紀街道與城市發展歷程。導覽員會介紹主教座堂、古羅馬遺跡與隱藏廣場故事。沿途可欣賞狹窄巷弄中保存良好的歷史建築細節。適合第一次到巴賽隆納又喜歡老城風景的旅人。', 'Barcelona Cathedral 正門', '巴賽隆納', 2.176900, 41.383900, '2026-07-21 19:30:58'),
(25, 2, 5, '巴賽隆納高第建築藝術導覽', '從高第獨特的建築語言認識巴賽隆納的藝術城市風格。導覽會介紹曲線結構、自然元素和馬賽克裝飾的設計概念。行程包含重要地標周邊與適合拍攝建築細節的位置。適合喜歡設計、建築與藝術文化的旅人。', 'Casa Batlló 門口', '巴賽隆納', 2.164900, 41.391700, '2026-07-21 19:30:58'),
(26, 5, 6, '巴賽隆納街頭人像旅拍體驗', '跟著攝影師走進巴賽隆納充滿色彩的街道與特色廣場。依照你的穿搭和風格安排適合的人像拍攝角度與背景。過程中會捕捉自然互動與旅行途中最放鬆的瞬間。完成後提供精選修圖照片，留下鮮明的城市回憶。', 'Arc de Triomf 前', '巴賽隆納', 2.180900, 41.391100, '2026-07-21 19:30:58'),
(27, 2, 7, '慕尼黑宮廷藝術博物館導覽', '走進慕尼黑宮廷博物館認識巴伐利亞王室留下的藝術收藏。導覽員會介紹珍貴畫作、珠寶與華麗宮廷空間的歷史。用淺顯方式說明藝術品背後的人物故事與時代背景。適合想深入認識德國歷史文化的旅人。', 'Residenz München 正門', '慕尼黑', 11.577800, 48.142200, '2026-07-21 19:30:58'),
(28, 3, 8, '慕尼黑傳統市集美食體驗之旅', '走訪慕尼黑人氣市集，品嚐香腸、起司與當季烘焙點心。導覽員會介紹巴伐利亞飲食文化和食材搭配的習慣。沿途可嘗試在地人常買的小吃與經典啤酒花園料理。適合想用味覺快速認識慕尼黑生活的旅人。', 'Viktualienmarkt 正門', '慕尼黑', 11.576100, 48.135100, '2026-07-21 19:30:58'),
(29, 5, 9, '阿姆斯特丹運河人像旅拍體驗', '在阿姆斯特丹運河與山形屋背景前拍下自然旅行寫真照片。攝影師會依照光線和街景安排適合你的拍攝路線與姿勢。行程包含橋梁、自行車街景與充滿生活感的河畔畫面。完成後提供精選照片，讓你帶走專屬城市記憶。', 'Magere Brug 橋頭', '阿姆斯特丹', 4.907400, 52.358300, '2026-07-21 19:30:58'),
(30, 4, 10, '阿姆斯特丹森林單車探索之旅', '騎著單車走進阿姆斯特丹森林，感受城市外圍的自然綠意。路線經過林間小徑、湖畔景觀與適合停留拍照的空間。導覽員會分享荷蘭人日常騎車與戶外休閒文化故事。適合喜歡輕度運動和自然風景的旅人。', 'Amsterdamse Bos 入口', '阿姆斯特丹', 4.839600, 52.325500, '2026-07-21 19:30:58'),
(31, 5, 5, '巴黎左岸晨光街拍漫遊之旅', '由攝影師帶你走入左岸晨光街景，捕捉自然互動與生活感畫面。沿途安排咖啡館與石板路取景，留下不刻意卻有故事的人像。提供簡單姿勢引導，第一次拍攝也能自在面對鏡頭。旅程結束後可獲得精選照片，收藏巴黎最溫柔的片刻。', 'Saint-Germain-des-Prés 地鐵站出口', '巴黎', 2.333300, 48.853400, '2026-07-21 20:14:21'),
(32, 3, 3, '法式市集私廚午宴品味體驗', '從早晨市集挑選當季食材，認識法國家庭料理重視的新鮮風味。跟著私廚完成前菜、主餐與甜點，學習實用的料理技巧。用餐時分享餐酒搭配與餐桌文化，感受道地生活節奏。適合想以味蕾深入認識巴黎的人，一起享受悠閒午宴。', 'Marché Bastille 市集入口', '巴黎', 2.369700, 48.853000, '2026-07-21 20:14:21'),
(33, 2, 2, '奧賽名畫故事藝術深度導覽', '從印象派代表作品出發，理解畫家如何用光線記錄巴黎的城市樣貌。導覽員會用容易理解的故事，帶你認識作品背後的人物與時代。避開艱深術語，讓第一次欣賞藝術也能找到自己的感動。行程保留自由觀賞時間，慢慢欣賞最喜歡的畫作。', 'Musée d\'Orsay 主入口前', '巴黎', 2.326600, 48.860000, '2026-07-21 20:14:21'),
(34, 1, 1, '泰晤士河畔古蹟漫步導覽之旅', '沿著泰晤士河步行，從經典地標認識倫敦不同時代留下的故事。導覽員會分享皇室、文學與城市發展的趣聞，讓街景不再只是照片背景。途中安排適合拍照的河岸角度，記錄旅程中的自然瞬間。適合第一次到倫敦，想快速掌握城市歷史脈絡的旅人。', 'Westminster 地鐵站 1 號出口', '倫敦', -0.127600, 51.500700, '2026-07-21 20:14:21'),
(35, 4, 4, '皇家公園單車綠意探索之旅', '騎著單車穿越倫敦皇家公園，從綠地與湖畔感受城市另一種悠閒節奏。路線平緩好騎，適合沒有單車經驗也想輕鬆探索的旅人。途中會停留隱藏花園與經典景點，兼顧拍照與休息時間。跟著在地帶領者前進，發現觀光地圖以外的清新風景。', 'Hyde Park Corner 地鐵站外', '倫敦', -0.159600, 51.503300, '2026-07-21 20:14:21'),
(36, 6, 6, '西區經典舞台劇夜遊體驗之旅', '夜幕降臨後走進西區街頭，感受劇院燈光與人群交織的熱鬧氛圍。帶領者會介紹經典劇院歷史，以及熱門音樂劇背後的小故事。演出前保留時間讓你挑選紀念品、拍照或品嚐附近小點。適合喜歡表演藝術，想體驗倫敦夜晚文化魅力的旅人。', 'Leicester Square 地鐵站出口', '倫敦', -0.128100, 51.511900, '2026-07-21 20:14:21'),
(37, 3, 3, '巴伐利亞家常料理手作體驗', '在溫暖的料理空間中學習巴伐利亞家庭常見菜色，感受樸實豐富的味道。從備料到擺盤都有主廚示範，讓每個步驟都能輕鬆跟上。完成後一起分享料理，認識當地人聚餐時重視的餐桌習慣。適合想離開觀光餐廳，親手體驗慕尼黑日常風味的旅人。', 'Viktualienmarkt 正門入口', '慕尼黑', 11.576100, 48.135100, '2026-07-21 20:14:21'),
(38, 2, 2, '慕尼黑宮廷藝術典藏導覽之旅', '走入昔日王室收藏空間，欣賞宮廷建築、人體藝術與珍貴裝飾作品。導覽員用生動故事介紹巴伐利亞王室，讓歷史人物更加貼近生活。行程安排重點展廳與拍照角度，避免在龐大館舍中迷失方向。適合喜歡藝術與歐洲歷史，希望深入認識慕尼黑文化的旅人。', 'Residenz München 售票處前', '慕尼黑', 11.577800, 48.141400, '2026-07-21 20:14:21'),
(39, 5, 5, '慕尼黑老城人像旅拍寫真體驗', '跟著在地攝影師走進老城廣場與彩色街角，拍下自然又有旅行感的人像。拍攝前會先了解你的穿搭與風格，安排最適合的取景路線。攝影師提供表情與動作引導，不必擔心面對鏡頭會尷尬。完成後取得精選成品，帶走一份有溫度的慕尼黑回憶。', 'Marienplatz 新市政廳前', '慕尼黑', 11.575500, 48.137400, '2026-07-21 20:14:21'),
(40, 1, 1, '運河金色年代歷史漫步導覽', '沿著運河與老宅漫步，認識阿姆斯特丹從貿易港口發展而來的歷史。導覽員會分享商人宅邸、倉庫與橋梁背後的城市生活故事。路線穿插較少遊客知道的巷弄，感受水都安靜而迷人的一面。適合想慢慢走讀城市，不只拍照打卡的文化旅行者。', 'Dam Square 國家紀念碑前', '阿姆斯特丹', 4.893600, 52.373100, '2026-07-21 20:14:21'),
(41, 4, 4, '風車村落單車田園探索之旅', '騎車前往運河旁的田園與風車村，感受阿姆斯特丹近郊開闊的風景。帶領者會安排平緩安全的路線，讓旅人能自在欣賞沿途景色。途中介紹乳酪、木鞋與水利文化，理解荷蘭人如何與水共存。適合喜歡戶外活動，也想拍下明亮鄉村畫面的旅人。', 'Amsterdam Centraal 車站前廣場', '阿姆斯特丹', 4.900300, 52.379100, '2026-07-21 20:14:21'),
(42, 6, 6, '城市秘境爵士夜生活體驗之旅', '傍晚走入運河旁的特色酒吧與爵士空間，感受城市夜晚的自在節奏。帶領者會介紹不同音樂場地的故事，找到旅人較少知道的演出角落。行程包含一杯在地飲品，讓你自然融入阿姆斯特丹夜生活。適合喜歡音樂、社交與輕鬆氛圍的成年旅人參加。', 'Leidseplein 廣場中央', '阿姆斯特丹', 4.881000, 52.364700, '2026-07-21 20:14:21'),
(43, 2, 2, '威尼斯面具工坊藝術導覽體驗', '走進傳統面具工坊，認識威尼斯嘉年華面具的色彩、工法與象徵意義。職人會示範手工裝飾細節，讓你看見精緻作品背後需要的耐心。導覽過程分享面具在戲劇與社交文化中的重要角色。適合喜歡手作藝術，也想認識水都另一面歷史的旅人。', 'Campo Santo Stefano 廣場中央', '威尼斯', 12.327900, 45.431300, '2026-07-21 20:14:21'),
(44, 3, 3, '潟湖海鮮市集風味品嚐體驗', '跟著在地嚮導走訪早晨市場，認識潟湖漁獲與威尼斯家庭料理的特色。品嚐新鮮海鮮小點與地方酒飲，感受不同於觀光餐廳的真實風味。帶領者會分享食材季節與點餐技巧，讓你之後也能自在探索。適合喜歡美食與市場文化，希望用味蕾旅行的旅人。', 'Rialto Market 市集入口', '威尼斯', 12.336000, 45.439000, '2026-07-21 20:14:21'),
(45, 5, 5, '水都晨霧人像旅拍寫真之旅', '清晨走進光線柔和的運河街景，避開人潮拍下最有水都氣氛的人像照片。攝影師會依照你的風格安排橋梁、小船與巷弄作為拍攝背景。過程提供自然動作引導，讓照片保有旅行中的真實情緒。適合情侶、好友或獨旅者，留下獨一無二的威尼斯紀念。', 'Ponte dell\'Accademia 橋頭', '威尼斯', 12.328800, 45.430800, '2026-07-21 20:14:21'),
(46, 1, 1, '總督宮秘史古蹟深度導覽之旅', '走進總督宮華麗廳堂與隱密走道，認識威尼斯共和國昔日的權力核心。導覽員會用人物故事解說政治、藝術與法律如何交織在同一座建築。除了經典景點，也帶你留意容易忽略的壁畫與建築細節。適合想深入理解威尼斯歷史，而非只匆匆參觀的旅人。', 'Doge\'s Palace 售票處前', '威尼斯', 12.340000, 45.433700, '2026-07-21 20:14:21'),
(47, 4, 4, '海岸步道夕陽健行探索之旅', '沿著海岸步道前進，從高處欣賞地中海海風、城市天際線與夕陽變化。路線難度適中，途中安排休息點讓大家能拍照與補充體力。嚮導會分享當地自然地形與居民生活，讓健行不只是走路。適合喜歡戶外景色，也想遠離市中心人潮的旅人參加。', 'Barceloneta 海灘鐘塔前', '巴賽隆納', 2.193500, 41.376300, '2026-07-21 20:14:21'),
(48, 6, 6, '加泰隆尼亞燈光夜生活體驗', '從熱鬧廣場出發探索夜晚街區，感受加泰隆尼亞城市獨有的活力與節奏。帶領者會介紹特色酒吧、音樂空間與適合拍照的燈光街景。行程保留自由交流時間，讓旅人能用自己的步調享受夜晚。適合成年旅客參加，喜歡社交、音樂與城市夜色的人。', 'Plaça de Catalunya 廣場中央', '巴賽隆納', 2.170100, 41.387000, '2026-07-21 20:14:21'),
(49, 2, 2, '畢卡索足跡藝術故事導覽之旅', '循著畢卡索早年在巴賽隆納留下的足跡，認識他如何受到城市文化啟發。導覽員會連結街區、藝術學院與作品故事，讓畫家的成長歷程更立體。行程以輕鬆方式介紹現代藝術，不需要任何專業背景也能理解。適合想從城市街景走進藝術世界的旅人參加。', 'Museu Picasso Barcelona 門口', '巴賽隆納', 2.181600, 41.385100, '2026-07-21 20:14:21'),
(50, 3, 3, '地中海市場料理手作體驗之旅', '從市場採買新鮮蔬果與海鮮，認識地中海料理重視簡單食材的美味。跟著主廚完成多道家常菜，學習橄欖油、香料與火候的搭配方式。用餐時分享巴賽隆納飲食文化，感受熱情自在的餐桌氣氛。適合想親手做菜，也想深入了解當地生活的美食旅人。', 'Mercat de la Boqueria 正門', '巴賽隆納', 2.172300, 41.382600, '2026-07-21 20:14:21'),
(51, 1, 1, '皇家衛兵儀式深度導覽體驗', '從白金漢宮周邊出發，認識衛兵交接儀式的歷史背景與觀看重點。帶你走訪王室地標並分享最佳拍攝角度。以輕鬆節奏了解倫敦的王室文化。適合第一次造訪倫敦的旅人。', 'Buckingham Palace 正門前', '倫敦', -0.141890, 51.501364, '2026-07-23 09:25:43'),
(52, 4, 4, '泰晤士河畔夜景攝影散步之旅', '沿著泰晤士河畔展開黃昏散步，欣賞倫敦眼與大笨鐘逐漸亮起的夜景。帶領你尋找適合拍照的河岸視角。途中會分享城市地標背後的小故事。適合喜歡夜景與慢旅行的人。', 'Westminster Bridge 北端', '倫敦', -0.121819, 51.500729, '2026-07-23 09:25:43'),
(53, 5, 5, '攝政公園晨光人像攝影體驗', '在柔和晨光中於攝政公園進行自然風格人像拍攝。攝影師會協助引導姿勢與表情，讓畫面看起來更放鬆自然。行程會結合草地、湖畔與樹蔭場景。留下專屬於倫敦旅行的照片記憶。', 'Regent\'s Park 南門', '倫敦', -0.152778, 51.531270, '2026-07-23 09:25:43'),
(54, 6, 6, '西區歌劇魅影夜晚觀賞體驗', '走進倫敦西區劇院，欣賞經典音樂劇的舞台魅力與現場演出能量。行前會介紹劇院文化與觀賞禮儀。演出後可在周邊街區散步感受夜晚氛圍。適合想體驗倫敦娛樂文化的旅人。', 'His Majesty\'s Theatre 門口', '倫敦', -0.131705, 51.509439, '2026-07-23 09:25:43'),
(55, 2, 2, '羅浮宮人體藝術深度導覽之旅', '由導覽員帶領認識羅浮宮的重要館藏與人體藝術發展脈絡。避開容易迷路的動線，將有限時間放在最值得看的作品。途中會分享畫作背後的故事與時代背景。適合想深入理解藝術而非只打卡的旅人。', 'Musée du Louvre 金字塔前', '巴黎', 2.336443, 48.860611, '2026-07-23 09:25:43'),
(56, 3, 3, '左岸私廚法式晚餐品味之夜', '在巴黎左岸的私廚空間品嘗以當季食材設計的法式料理。主廚會介紹料理靈感與搭配方式，讓用餐不只是吃一頓飯。餐桌氣氛輕鬆並可與其他旅人交流。適合喜歡美食與生活感體驗的人。', 'Saint-Germain-des-Prés 附近', '巴黎', 2.333333, 48.854722, '2026-07-23 09:25:43'),
(57, 5, 5, '塞納河畔黃昏人像旅拍體驗', '在塞納河畔與巴黎街角進行黃昏人像拍攝，捕捉城市最柔和的光線。攝影師會協助規劃拍攝路線與自然互動姿勢。畫面將結合橋梁、河景與經典建築。適合情侶、朋友或獨旅紀念。', 'Pont Alexandre III 橋旁', '巴黎', 2.313644, 48.863796, '2026-07-23 09:25:43'),
(58, 1, 1, '聖心堂街區故事漫步導覽體驗', '從蒙馬特山腳慢慢步行至聖心堂，認識藝術家與街頭文化留下的痕跡。導覽員會分享街區轉角的小故事與私房視角。沿途可欣賞巴黎市景與特色店家。適合喜歡歷史與散步節奏的旅人。', 'Anvers 地鐵站出口', '巴黎', 2.344720, 48.882117, '2026-07-23 09:25:43'),
(59, 2, 2, '現代藝術館策展深度導覽體驗', '走進慕尼黑現代藝術館，從策展角度理解作品之間的關聯與時代脈絡。導覽會用容易理解的方式拆解抽象藝術概念。途中保留時間讓你提問與交流觀察。適合對當代藝術感到好奇的旅人。', 'Pinakothek der Moderne 門口', '慕尼黑', 11.574724, 48.147755, '2026-07-23 09:25:43'),
(60, 3, 3, '巴伐利亞家常料理手作體驗', '在溫暖的料理空間學習製作巴伐利亞家庭常見菜色與點心。從備料、調味到擺盤都會親自參與，完成後一起享用成果。主廚也會分享德國飲食文化與採買技巧。適合喜歡動手做料理的旅人。', 'Viktualienmarkt 正門入口', '慕尼黑', 11.576124, 48.135125, '2026-07-23 09:25:43'),
(61, 6, 6, '傳統啤酒館現場音樂之夜體驗', '走進具有在地氣氛的傳統啤酒館，感受現場音樂與慕尼黑夜生活文化。行程包含認識不同啤酒風味與基本飲用禮儀。也會介紹啤酒節背後的歷史由來。適合想融入當地熱鬧氛圍的旅人。', 'Hofbräuhaus München 門口', '慕尼黑', 11.580437, 48.137430, '2026-07-23 09:25:43'),
(62, 2, 2, '梵谷博物館名作深度導覽之旅', '透過精選館藏認識梵谷不同時期的創作轉變與人生故事。導覽員會說明色彩、筆觸與構圖背後想傳達的情感。避開走馬看花的參觀方式，專注理解幾件代表作品。適合喜歡藝術與人物故事的旅人。', 'Van Gogh Museum 主入口', '阿姆斯特丹', 4.881094, 52.358416, '2026-07-23 09:25:43'),
(63, 4, 4, '運河單車晨光探索漫遊體驗', '騎著單車穿梭阿姆斯特丹運河與安靜街區，感受城市剛甦醒的節奏。路線會避開最擁擠的觀光區，保留更多在地生活畫面。途中停靠幾個適合拍照與休息的角落。適合喜歡自由探索與戶外活動的旅人。', 'Amsterdam Centraal Station 前廣場', '阿姆斯特丹', 4.900272, 52.379189, '2026-07-23 09:25:43'),
(64, 6, 6, '運河酒吧現場爵士微醺之夜', '在運河旁的特色酒吧聆聽現場爵士樂，感受阿姆斯特丹夜晚悠閒又有活力的氣氛。行程會介紹酒吧文化與推薦飲品風格。可與同行旅人自在聊天交流。適合喜歡音樂、夜景與慢節奏社交的人。', 'Leidseplein 廣場旁', '阿姆斯特丹', 4.881076, 52.363878, '2026-07-23 09:25:43'),
(65, 1, 1, '總督宮歷史秘聞深度導覽之旅', '走進總督宮認識威尼斯共和國的政治制度、藝術裝飾與權力故事。導覽員會帶你留意一般參觀容易忽略的建築細節。透過宮殿空間理解城市昔日的海洋霸權。適合喜歡歷史、建築與故事性導覽的旅人。', 'Palazzo Ducale 正門前', '威尼斯', 12.340432, 45.433666, '2026-07-23 09:25:43'),
(66, 2, 2, '威尼斯雙年展藝術路線導覽體驗', '沿著雙年展周邊展館與街區探索當代藝術如何走進威尼斯日常。導覽員會挑選易理解的作品，分享創作概念與觀展方法。行程兼顧藝術內容與城市散步樂趣。適合第一次接觸雙年展的旅人。', 'Giardini della Biennale 入口', '威尼斯', 12.360230, 45.430107, '2026-07-23 09:25:43'),
(67, 4, 4, '潟湖日落划船自然探索體驗', '在專業帶領下於威尼斯潟湖划船，從水面欣賞遠離人潮的島嶼與天際線。行程會配合日落時段，感受光線在水面變化的美景。途中分享潟湖生態與城市水路故事。適合喜歡自然與安靜戶外體驗的旅人。', 'Fondamente Nove 碼頭', '威尼斯', 12.342140, 45.445140, '2026-07-23 09:25:43'),
(68, 1, 1, '聖家堂建築細節深度導覽體驗', '從聖家堂外觀到內部光影，認識高第如何把自然元素融入建築設計。導覽員會解說立面雕刻、柱體與彩色玻璃的象徵意義。讓你不只拍照，也能理解這座建築的獨特語言。適合喜歡設計與建築故事的旅人。', 'Sagrada Família 主入口前', '巴塞隆納', 2.174355, 41.403629, '2026-07-23 09:25:43'),
(69, 3, 3, '波蓋利亞市場小吃品味之旅', '走進熱鬧的波蓋利亞市場，認識西班牙火腿、起司與海鮮小吃的在地吃法。導覽會安排幾個特色攤位，邊品嘗邊了解食材來源。也會分享市場採買與避開人潮的小技巧。適合想用味蕾認識巴塞隆納的旅人。', 'Mercat de la Boqueria 正門', '巴塞隆納', 2.171603, 41.381682, '2026-07-23 09:25:43'),
(70, 5, 5, '哥德區街景人像旅拍攝影體驗', '在哥德區石牆巷弄與廣場之間進行人像拍攝，留下帶有歐洲舊城氣氛的旅行照片。攝影師會依光線安排自然好看的取景位置。過程不需擔心姿勢，會提供簡單引導。適合獨旅、情侶與朋友同行紀念。', 'Barcelona Cathedral 前廣場', '巴塞隆納', 2.176943, 41.383962, '2026-07-23 09:25:43'),
(71, 2, 2, '泰特現代館人體藝術導覽之旅', '走進泰特現代美術館認識人體藝術與現代創作的表現方式。導覽員會用淺顯方式說明作品的背景與觀看重點。行程保留提問時間，讓你更自在地接近當代藝術。', 'Tate Modern 主入口', '倫敦', -0.099356, 51.507596, '2026-07-23 10:07:01'),
(72, 3, 3, '波羅市場街頭美食探索之旅', '跟著在地嚮導穿梭波羅市場，品嘗英國起司、烘焙點心與特色街頭料理。途中會介紹攤商故事與食材來源。適合想用味蕾認識倫敦日常生活的旅人。', 'Borough Market 正門', '倫敦', -0.091144, 51.505482, '2026-07-23 10:07:01'),
(73, 4, 4, '海德公園湖畔野餐探索體驗', '在海德公園的湖畔與草地間散步，感受倫敦人悠閒的戶外生活。行程會安排簡單野餐與自然觀察時間。適合喜歡公園、散步與慢旅行節奏的旅人。', 'Hyde Park Speaker\'s Corner', '倫敦', -0.158210, 51.512050, '2026-07-23 10:07:01'),
(74, 5, 5, '諾丁丘彩色街景人像旅拍體驗', '在諾丁丘繽紛的彩色屋與安靜巷弄中進行自然人像拍攝。攝影師會協助引導姿勢與表情，不需要有拍照經驗。完成後能留下充滿倫敦街頭感的旅行紀念。', 'Notting Hill Gate Station', '倫敦', -0.196646, 51.508905, '2026-07-23 10:07:01'),
(75, 6, 6, '柯芬園劇場後台文化體驗之旅', '走訪柯芬園周邊劇場與表演空間，認識倫敦西區的娛樂文化。導覽員會分享劇院歷史、演員故事與觀賞禮儀。適合喜歡舞台表演與城市夜生活的人。', 'Covent Garden Piazza', '倫敦', -0.122958, 51.511700, '2026-07-23 10:07:01'),
(76, 1, 1, '巴黎聖母院歷史故事導覽體驗', '從巴黎聖母院周邊出發，認識哥德式建築與城市歷史留下的痕跡。導覽員會分享文學故事與修復工程背景。讓你不只看見地標，也理解它對巴黎的重要意義。', 'Notre-Dame Cathedral 前方', '巴黎', 2.349902, 48.853000, '2026-07-23 10:07:01'),
(77, 3, 3, '蒙馬特小酒館晚餐品味之夜', '在蒙馬特山腳的小酒館享用經典法式晚餐與當季料理。主廚會介紹餐點搭配與法國餐桌文化。用餐後可在夜晚街區散步，感受藝術村特有的浪漫氣氛。', 'Abbesses Station 出口', '巴黎', 2.338680, 48.884116, '2026-07-23 10:07:01'),
(78, 4, 4, '塞納河畔晨跑城市探索體驗', '沿著塞納河岸以輕鬆步調晨跑，經過橋梁、書報攤與經典城市景觀。帶領者會依參加者狀況調整速度。適合想在旅行中維持運動習慣並探索巴黎的人。', 'Pont Neuf 橋旁', '巴黎', 2.341211, 48.857050, '2026-07-23 10:07:01'),
(79, 5, 5, '瑪黑街區午後自然人像旅拍', '在瑪黑區的石板路、拱廊與咖啡館外拍攝自然風格旅行照片。攝影師會依光線安排合適取景位置。過程輕鬆不趕行程，適合獨旅或朋友同行留下紀念。', 'Place des Vosges 廣場', '巴黎', 2.365404, 48.855420, '2026-07-23 10:07:01'),
(80, 6, 6, '拉丁區爵士酒吧微醺音樂夜', '走進拉丁區的特色爵士酒吧，感受現場音樂與巴黎夜生活氛圍。行程會介紹不同酒吧文化與推薦飲品。適合喜歡音樂、聊天與夜晚散步的旅人。', 'Odéon Station 出口', '巴黎', 2.339746, 48.849089, '2026-07-23 10:07:01'),
(81, 1, 1, '寧芬堡宮皇家花園導覽體驗', '漫步寧芬堡宮與皇家花園，認識巴伐利亞王室生活與宮廷建築特色。導覽員會分享宮殿空間背後的歷史故事。適合喜歡歐洲宮殿、花園與攝影的旅人。', 'Nymphenburg Palace 正門', '慕尼黑', 11.531563, 48.158340, '2026-07-23 10:07:01'),
(82, 2, 2, '德意志博物館科技深度導覽', '走進德意志博物館探索交通、能源與科學發展的重要展品。導覽會用生活化方式解釋複雜科技原理。適合喜歡工程、發明與互動展覽的旅人。', 'Deutsches Museum 主入口', '慕尼黑', 11.583900, 48.129900, '2026-07-23 10:07:01'),
(83, 4, 4, '英式花園單車湖畔漫遊體驗', '騎著單車穿梭英式花園的大草地與湖畔步道，感受慕尼黑人最喜歡的休閒方式。途中會停靠特色景點與觀景角落。適合想輕鬆探索城市綠地的旅人。', 'Englischer Garten 南入口', '慕尼黑', 11.590803, 48.154850, '2026-07-23 10:07:01'),
(84, 5, 5, '慕尼黑老城街頭人像旅拍體驗', '在瑪利亞廣場與老城巷弄中拍攝帶有歐洲建築風格的人像照片。攝影師會協助安排自然走動與互動畫面。適合想留下慕尼黑旅行紀念的獨旅與情侶。', 'Marienplatz 新市政廳前', '慕尼黑', 11.575490, 48.137154, '2026-07-23 10:07:01'),
(85, 6, 6, '啤酒花園民謠夜晚同樂體驗', '在慕尼黑傳統啤酒花園感受民謠演出與熱鬧的晚間氛圍。行程會介紹啤酒文化與基本點餐方式。適合想認識巴伐利亞在地社交生活的旅人。', 'Chinesischer Turm 啤酒花園', '慕尼黑', 11.592477, 48.155190, '2026-07-23 10:07:01'),
(86, 1, 1, '安妮之家歷史記憶導覽體驗', '從安妮之家周邊街區了解二戰時期阿姆斯特丹的生活記憶與歷史脈絡。導覽員會以尊重且易理解的方式分享故事。適合希望更深入理解城市歷史的旅人。', 'Anne Frank House 附近', '阿姆斯特丹', 4.883977, 52.375218, '2026-07-23 10:07:01'),
(87, 2, 2, '荷蘭國立博物館名作導覽之旅', '由導覽員帶領認識荷蘭黃金時代的重要畫作與藝術家故事。行程聚焦幾件代表作品，避免走馬看花。適合對林布蘭、維梅爾與歐洲藝術有興趣的旅人。', 'Rijksmuseum 主入口', '阿姆斯特丹', 4.885219, 52.359998, '2026-07-23 10:07:01'),
(88, 3, 3, '運河起司品鑑手作午茶體驗', '在運河旁的溫馨空間品嘗荷蘭起司、麵包與小點心。體驗會介紹不同熟成方式與風味搭配。適合喜歡下午茶、在地食材與悠閒聊天氛圍的旅人。', 'Nine Streets 附近', '阿姆斯特丹', 4.885472, 52.370488, '2026-07-23 10:07:01'),
(89, 5, 5, '約旦區運河晨光人像旅拍體驗', '在約旦區的運河、橋梁與晨光街景中拍攝自然風格照片。攝影師會幫你找到不擁擠又有城市感的取景點。適合想留下一組阿姆斯特丹旅行寫真的旅人。', 'Noordermarkt 廣場', '阿姆斯特丹', 4.887889, 52.379415, '2026-07-23 10:07:01'),
(90, 6, 6, '紅燈區夜遊文化故事體驗之旅', '透過在地導覽認識紅燈區的歷史、法律文化與城市多元面貌。行程以尊重居民與安全為原則，不打擾當地生活。適合想理解城市不同面向的成年旅人。', 'Dam Square 廣場', '阿姆斯特丹', 4.893604, 52.373093, '2026-07-23 10:07:01'),
(91, 1, 1, '彩色島玻璃工藝故事導覽體驗', '前往色彩鮮明的彩色島，認識島嶼居民生活與威尼斯潟湖文化。導覽員會分享玻璃工藝如何影響周邊社區。適合喜歡手作、建築色彩與慢旅行的旅人。', 'Burano 碼頭入口', '威尼斯', 12.416836, 45.485504, '2026-07-23 10:07:01'),
(92, 2, 2, '佩姬古根漢美術館導覽之旅', '走進大運河旁的佩姬古根漢美術館，認識二十世紀藝術收藏與創作者故事。導覽會說明作品與建築空間的關係。適合喜歡現代藝術與水岸景色的旅人。', 'Peggy Guggenheim Collection 前', '威尼斯', 12.329712, 45.430420, '2026-07-23 10:07:01'),
(93, 3, 3, '威尼斯海鮮小吃品味探索之旅', '穿梭威尼斯巷弄中的小酒館，品嘗海鮮小吃、燉飯與在地葡萄酒。導覽員會介紹點餐文化與經典料理來源。適合想避開觀光餐廳並認識在地味道的旅人。', 'Rialto Market 附近', '威尼斯', 12.335798, 45.439523, '2026-07-23 10:07:01'),
(94, 4, 4, '麗都島日落單車海岸探索體驗', '在麗都島沿著海岸騎單車，感受與主島不同的安靜海島氛圍。行程安排於日落前後，能欣賞海面光線變化。適合喜歡運動、海風與自然景觀的旅人。', 'Lido Santa Maria Elisabetta 碼頭', '威尼斯', 12.368112, 45.417740, '2026-07-23 10:07:01'),
(95, 6, 6, '面具工坊嘉年華文化體驗之旅', '走進傳統面具工坊，認識威尼斯嘉年華的歷史與面具製作工藝。可近距離觀看裝飾細節與材質特色。適合喜歡節慶文化、手作美學與拍照的旅人。', 'Campo Santo Stefano 廣場', '威尼斯', 12.327430, 45.432750, '2026-07-23 10:07:01'),
(96, 1, 1, '加泰隆尼亞廣場故事導覽體驗', '從加泰隆尼亞廣場出發，認識巴塞隆納城市發展與重要街區故事。導覽會串連老城與現代大道的歷史脈絡。適合第一次來訪並想快速理解城市樣貌的旅人。', 'Plaça de Catalunya 廣場', '巴塞隆納', 2.170082, 41.387019, '2026-07-23 10:07:01'),
(97, 2, 2, '畢卡索博物館名作導覽之旅', '透過畢卡索早期作品認識藝術家在巴塞隆納成長與創作轉變。導覽員會說明畫風、主題與時代背景。適合想從作品理解畢卡索而非只看知名畫作的旅人。', 'Museu Picasso Barcelona 前', '巴塞隆納', 2.180938, 41.385157, '2026-07-23 10:07:01'),
(98, 3, 3, '加泰隆尼亞海鮮燉飯手作體驗', '在專業廚師帶領下製作加泰隆尼亞風格海鮮燉飯與特色小菜。從挑選食材到掌握火候都能親自參與。適合喜歡料理、海鮮與西班牙飲食文化的旅人。', 'Mercat de Santa Caterina 附近', '巴塞隆納', 2.176700, 41.386410, '2026-07-23 10:07:01'),
(99, 4, 4, '蒙特惠奇山頂夕陽探索體驗', '搭配步行與纜車探索蒙特惠奇山的觀景平台、花園與城市歷史地標。行程安排於傍晚，能欣賞巴塞隆納日落景色。適合喜歡自然、城市全景與輕健行的旅人。', 'Montjuïc Cable Car 入口', '巴塞隆納', 2.166223, 41.363219, '2026-07-23 10:07:01'),
(100, 5, 5, '巴塞隆納海岸晨光人像旅拍體驗', '在巴塞隆納海岸與晨光沙灘拍攝輕鬆自然的人像旅行照片。攝影師會安排散步、互動與海景取景畫面。適合想留下陽光感歐洲旅行紀念的獨旅或情侶。 ', 'Barceloneta Beach 海灘入口', '巴塞隆納', 2.190394, 41.378315, '2026-07-23 10:07:01');

-- Continue AUTO_INCREMENT after imported seed data
ALTER TABLE `experiences` AUTO_INCREMENT = 101;

-- --------------------------------------------------------
-- Seed data for `sessions`
-- 共 100 個體驗 × 30 天 × 每天 2 場 = 6000 筆

-- 只有在 sessions 是空資料表、重新匯入 seed 時才需要這行
ALTER TABLE sessions AUTO_INCREMENT = 1;

INSERT INTO sessions (
  experience_id,
  start_time,
  end_time,
  booking_deadline,
  adult_price,
  child_price,
  min_participants,
  max_participants,
  status,
  created_at
)
WITH RECURSIVE date_list AS (
  -- 明天開始
  SELECT DATE_ADD(CURDATE(), INTERVAL 1 DAY) AS session_date

  UNION ALL

  -- 一共產生 30 天
  SELECT DATE_ADD(session_date, INTERVAL 1 DAY)
  FROM date_list
  WHERE session_date < DATE_ADD(CURDATE(), INTERVAL 30 DAY)
),

session_schedule AS (
  -- category_id, 第幾場, 開始時間, 體驗分鐘數

  -- 古蹟巡禮
  SELECT 1 AS category_id, 1 AS slot_no, '09:30:00' AS start_at, 150 AS duration_minutes
  UNION ALL SELECT 1, 2, '14:00:00', 150

  -- 藝文導覽
  UNION ALL SELECT 2, 1, '10:00:00', 150
  UNION ALL SELECT 2, 2, '14:30:00', 150

  -- 美饌饗宴：午餐、晚餐
  UNION ALL SELECT 3, 1, '12:00:00', 180
  UNION ALL SELECT 3, 2, '18:30:00', 180

  -- 戶外探索
  UNION ALL SELECT 4, 1, '09:00:00', 240
  UNION ALL SELECT 4, 2, '14:00:00', 240

  -- 專人攝影
  UNION ALL SELECT 5, 1, '10:00:00', 120
  UNION ALL SELECT 5, 2, '15:00:00', 120

  -- 娛樂與夜生活：晚上場
  UNION ALL SELECT 6, 1, '19:00:00', 210
  UNION ALL SELECT 6, 2, '21:30:00', 210
),

experience_base_price AS (
  SELECT
    e.id AS experience_id,
    e.category_id,

    CASE e.category_id
      WHEN 1 THEN 2200
      WHEN 2 THEN 2600
      WHEN 3 THEN 2400
      WHEN 4 THEN 1800
      WHEN 5 THEN 3000
      WHEN 6 THEN 2800
      ELSE 2000
    END AS weekday_adult_price

  FROM experiences e
  WHERE e.id BETWEEN 1 AND 100
)

SELECT
  e.experience_id,

  TIMESTAMP(d.session_date, ss.start_at) AS start_time,

  DATE_ADD(
    TIMESTAMP(d.session_date, ss.start_at),
    INTERVAL ss.duration_minutes MINUTE
  ) AS end_time,

  DATE_SUB(
    TIMESTAMP(d.session_date, ss.start_at),
    INTERVAL 24 HOUR
  ) AS booking_deadline,

  ROUND(
    e.weekday_adult_price *
    CASE
      WHEN DAYOFWEEK(d.session_date) IN (1, 7) THEN 1.2
      ELSE 1
    END,
    0
  ) AS adult_price,

  ROUND(
    e.weekday_adult_price * 0.7 *
    CASE
      WHEN DAYOFWEEK(d.session_date) IN (1, 7) THEN 1.2
      ELSE 1
    END,
    0
  ) AS child_price,

  2 AS min_participants,
  8 AS max_participants,
  1 AS status,
  NOW() AS created_at

FROM date_list d
CROSS JOIN session_schedule ss
INNER JOIN experience_base_price e
  ON e.category_id = ss.category_id

-- 這個排序讓第一天第一場的 ID 1～100，
-- 分別對應 experience_id 1～100
ORDER BY
  d.session_date ASC,
  ss.slot_no ASC,
  e.experience_id ASC;

-- --------------------------------------------------------
-- Seed data for `posts`

INSERT INTO `posts` (
  `title`,
  `slug`,
  `content`,
  `excerpt`,
  `cover_image`,
  `content_image`,
  `status`,
  `published_at`,
  `updated_at`,
  `created_at`,
  `author_id`,
  `category_id`,
  `order_item_id`,
  `experience_id`,
  `review_note`
)
WITH
city_copy AS (
  SELECT 1 AS city_order, '倫敦' AS city_name, 'london' AS city_key,
    'London' AS image_folder,
    '紅磚街區、河岸天際線與市場日常彼此交錯，適合用步行速度慢慢閱讀城市層次。' AS city_note
  UNION ALL
  SELECT 2, '巴黎', 'paris', 'Paris',
    '林蔭大道、街角咖啡館與歷史建築形成自然的生活舞台，白天與傍晚各有不同光線。'
  UNION ALL
  SELECT 3, '阿姆斯特丹', 'amsterdam', 'Amsterdam',
    '運河、窄屋與單車節奏構成鮮明風景，適合安排留白，觀察水面倒影與街區細節。'
  UNION ALL
  SELECT 4, '巴塞隆納', 'barcelona', 'Barcelona',
    '海岸陽光、現代主義建築與熱鬧街區並存，行程可以在文化觀察與放鬆之間取得平衡。'
  UNION ALL
  SELECT 5, '慕尼黑', 'munich', 'Munich',
    '王室建築、綠地與在地餐桌文化距離不遠，適合以明確主題串成一條舒適路線。'
  UNION ALL
  SELECT 6, '威尼斯', 'venice', 'Venice',
    '水巷、石橋與廣場會隨光線改變表情，避開急促打卡，更能感受城市獨特的尺度。'
),
category_copy AS (
  SELECT 1 AS category_id, '古蹟巡禮' AS category_label,
    '古城散步精選' AS title_one, '歷史街區指南' AS title_two,
    '觀察建築年代、城市紋理與街道格局，不只記住地標名稱，也理解不同時期如何共同塑造今日風景。' AS editorial_focus,
    '建議先掌握主要歷史節點，再把周邊巷弄與廣場排入路線；鞋子以好走為優先，並為臨時停留保留時間。' AS practical_focus
  UNION ALL
  SELECT 2, '藝文導覽', '藝術漫遊精選', '美術館散步',
    '把作品、展館空間與城市背景放在同一條敘事線上，讓藝術不只停留在展品說明，而能連回旅行當下的感受。',
    '大型展館不必一次看完，先選一至兩個主題；遇到喜歡的作品多停幾分鐘，比追求打卡數量更有收穫。'
  UNION ALL
  SELECT 3, '美饌饗宴', '餐桌風味精選', '在地美食指南',
    '從市場食材、料理方法與用餐節奏認識地方文化，重點不只是吃到名店，也包括理解一道菜為何出現在這座城市。',
    '熱門餐廳可先訂位，同時保留一餐給市場或街區小店；若有過敏與飲食限制，應在預約時清楚確認。'
  UNION ALL
  SELECT 4, '戶外探索', '戶外路線精選', '自然散步指南',
    '透過河岸、公園、海邊或城市近郊轉換觀看角度，在移動與停留之間找到適合自己的體力節奏。',
    '出發前確認天氣與日落時間，準備飲水、防曬和輕便外套；路線不必塞滿，安全與舒適應放在第一位。'
  UNION ALL
  SELECT 5, '專人攝影', '旅拍場景精選', '城市取景指南',
    '利用街道線條、自然光與城市色彩留下有情境的旅行影像，讓人物和環境彼此呼應，而不是只更換拍照背景。',
    '服裝以活動方便且色彩簡潔為佳，拍攝前可整理喜歡的氛圍參考；遇到人潮時，耐心等待通常比頻繁換點有效。'
  UNION ALL
  SELECT 6, '娛樂與夜生活', '夜間行程精選', '夜生活指南',
    '從表演、酒館、夜景與晚間街區感受城市下班後的樣貌，安排重點是氣氛、移動安全與結束時間。',
    '先確認演出入場規定與末班交通，飲酒保持適量；夜間移動以明亮主要道路為主，回程預留叫車備案。'
),
normalized_experiences AS (
  SELECT
    e.id,
    e.category_id,
    e.title,
    CASE
      WHEN e.city = '巴賽隆納' THEN '巴塞隆納'
      ELSE e.city
    END AS city_name,
    e.city AS original_city
  FROM `experiences` AS e
),
ranked_experiences AS (
  SELECT
    ne.id,
    ne.category_id,
    ne.title,
    ne.city_name,
    ROW_NUMBER() OVER (
      PARTITION BY ne.city_name, ne.category_id
      ORDER BY
        CASE
          WHEN ne.original_city = ne.city_name THEN 0
          ELSE 1
        END,
        ne.id
    ) AS choice_order
  FROM normalized_experiences AS ne
  INNER JOIN city_copy AS cc
    ON cc.city_name = ne.city_name
),
city_category_experiences AS (
  SELECT
    re.id AS experience_id,
    re.category_id,
    re.title AS experience_title,
    cc.city_order,
    cc.city_name,
    cc.city_key,
    cc.image_folder,
    cc.city_note,
    cat.category_label,
    cat.title_one,
    cat.title_two,
    cat.editorial_focus,
    cat.practical_focus
  FROM ranked_experiences AS re
  INNER JOIN city_copy AS cc
    ON cc.city_name = re.city_name
  INNER JOIN category_copy AS cat
    ON cat.category_id = re.category_id
  WHERE re.choice_order = 1
),
article_numbers AS (
  SELECT 1 AS article_number
  UNION ALL
  SELECT 2
),
article_source AS (
  SELECT
    combo.*,
    numbers.article_number,
    MOD(
      combo.city_order + combo.category_id + numbers.article_number,
      6
    ) AS layout_variant,
    ((combo.category_id - 1) * 4)
      + ((numbers.article_number - 1) * 2)
      + 1 AS cover_number,
    (
      (
        ((combo.category_id - 1) * 2)
        + (numbers.article_number - 1)
      ) * 6
    ) + (combo.city_order - 1) AS publish_order,
    CASE
      WHEN numbers.article_number = 1
        THEN '以第一次造訪者的角度安排重點，先建立清楚方向，再把現場感受留給步行途中慢慢補上。'
      ELSE '以想看得更深入的旅人為出發點，避開只追逐熱門清單，改用主題、時間與街區氣氛組織行程。'
    END AS article_angle,
    CASE
      WHEN numbers.article_number = 1
        THEN '上午先處理最需要專注的內容，中段安排休息，傍晚再用較輕鬆的方式收尾。'
      ELSE '先選一個核心體驗，再搭配周邊一至兩個停留點，讓移動距離合理，也保留臨時改變計畫的彈性。'
    END AS route_advice
  FROM city_category_experiences AS combo
  CROSS JOIN article_numbers AS numbers
)
SELECT
  CONCAT(
    source.city_name,
    CASE
      WHEN source.article_number = 1 THEN source.title_one
      ELSE source.title_two
    END
  ) AS title,

  CONCAT(
    'official-',
    source.city_key,
    '-category-',
    source.category_id,
    '-',
    source.article_number
  ) AS slug,

  CONCAT(
    '<h2>',
    source.city_name,
    '｜',
    source.category_label,
    CASE
      WHEN source.article_number = 1 THEN '編輯精選'
      ELSE '深度指南'
    END,
    '</h2>',

    CASE source.layout_variant
      WHEN 0 THEN CONCAT(
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label,
        '"><figcaption>', source.city_name, '的',
        source.category_label, '旅行視角</figcaption></figure>',
        '<p><span class="marker-yellow">編輯部路線觀察：</span>',
        source.city_note, source.article_angle,
        '這篇內容以「', source.experience_title,
        '」作為認識城市的起點。', source.editorial_focus,
        '實際安排時不必急著把所有景點塞進一天，先確定最想理解的主題，旅程會更有記憶點。</p>',
        '<blockquote><p>', source.route_advice,
        '若現場狀況與預期不同，也可以縮短次要停留，把時間留給真正喜歡的地方。</p></blockquote>',
        '<p>', source.practical_focus,
        '此外，交通、營業時間與預約規則可能因季節調整，出發前仍應查看最新公告。好的行程不是完成最多項目，而是在適合的節奏裡看見城市細節，並帶著足夠餘裕安全返回。</p>'
      )

      WHEN 1 THEN CONCAT(
        '<figure class="image image-style-side"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label, '側景"></figure>',
        '<p><span class="marker-green">從一個主題開始：</span>',
        source.city_note, '本篇選擇「', source.experience_title,
        '」作為核心，是因為它能把地點、故事與實際參與感連在一起。', source.editorial_focus,
        source.article_angle,
        '與其把文章當成固定答案，更適合把它視為可依天氣、同行者與體力調整的行程底稿。</p>',
        '<h3>安排時先確認</h3>',
        '<ul><li>核心體驗的集合時間、語言及入場方式</li>',
        '<li>體驗前後的移動距離與休息地點</li>',
        '<li>當日天氣、服裝及必要預約</li></ul>',
        '<div class="page-break"></div>',
        '<p>', source.route_advice, source.practical_focus,
        '如果只剩半天，也可以保留核心內容並刪除繞路景點；如果時間充足，則可在附近安排一段沒有目的的散步。這種鬆緊交替的節奏，更容易留下屬於自己的城市印象。</p>'
      )

      WHEN 2 THEN CONCAT(
        '<blockquote><p>旅行不必把每個地標都變成任務；選對觀看角度，比增加清單長度更重要。</p></blockquote>',
        '<p>', source.city_name, '的', source.category_label,
        '適合先從「', source.experience_title,
        '」建立方向。', source.city_note, source.editorial_focus,
        source.article_angle,
        '編輯部建議在出發前只設定一個主要目標，其他停留則依現場氣氛決定，既能避免趕路，也不會失去探索感。</p>',
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label,
        '"><figcaption>為主要體驗前後保留散步時間</figcaption></figure>',
        '<figure class="table"><table><tbody>',
        '<tr><th>時間安排</th><td>', source.route_advice, '</td></tr>',
        '<tr><th>現場準備</th><td>', source.practical_focus, '</td></tr>',
        '<tr><th>編輯提醒</th><td>保留備案並確認最新營業資訊，不因拍照或打卡影響安全。</td></tr>',
        '</tbody></table></figure>',
        '<p>完成主要體驗後，可以找一個安靜位置整理照片與筆記，再決定是否繼續下一站。這段整理時間能讓資訊沉澱，也能及早察覺疲勞。只要主題清楚，即使行程不長，仍能形成完整而有層次的一天。</p>'
      )

      WHEN 3 THEN CONCAT(
        '<p><span class="marker-blue">本日提案：</span>用',
        source.category_label, '重新閱讀', source.city_name,
        '。', source.city_note, '我們以「', source.experience_title,
        '」為路線核心，並把附近街區當成延伸而非附加任務。', source.editorial_focus,
        source.article_angle,
        '這樣安排可以降低交通轉換，也能在同一區域裡看見白天與傍晚不同的表情。</p>',
        '<figure class="image image-style-side"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, '街區細節"></figure>',
        '<h3>把節奏留給現場</h3>',
        '<p>', source.route_advice, source.practical_focus,
        '遇到喜歡的空間可以多停留，不需要為了原定清單立刻離開；如果人潮過多，也可先到周邊散步再返回。旅行品質常由這些小幅調整決定，而不是由完成多少景點衡量。</p>',
        '<div class="page-break"></div>',
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 2, 2, '0'),
        '.jpg" alt="', source.city_name, '行程收尾"><figcaption>用較安靜的畫面替行程收尾</figcaption></figure>'
      )

      WHEN 4 THEN CONCAT(
        '<figure class="image"><img src="/',
        source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, source.category_label,
        '主題照片"></figure>',
        '<p>', source.city_name, '的魅力很難只用一張清單說完。站在',
        source.category_label, '的角度，這篇以「',
        source.experience_title, '」作為具體入口。', source.city_note,
        source.editorial_focus, source.article_angle,
        '先理解核心體驗的特色，再挑選周邊停留點，可以避免行程彼此搶時間，也讓照片、味道與故事形成連續記憶。</p>',
        '<h3>三個實用步驟</h3>',
        '<ol><li>確認核心體驗的時間與集合位置，反推當日出發時間。</li>',
        '<li>', source.route_advice, '</li>',
        '<li>預留休息與回程空間，並準備一個天候不佳時的替代方案。</li></ol>',
        '<p>', source.practical_focus,
        '旅途中若發現原定地點不符合期待，可以直接調整，不必勉強完成。把注意力放在感受與安全上，通常會比追求完美行程得到更多，也更適合與同行者共同留下舒服的回憶。</p>'
      )

      ELSE CONCAT(
        '<p><span class="marker-pink">編輯部雙視角：</span>一邊看',
        source.city_name, '的代表場景，一邊把',
        source.category_label, '放進真實旅行節奏。這次以「',
        source.experience_title, '」為主題。', source.city_note,
        source.editorial_focus, source.article_angle,
        '我們不追求密集踩點，而是讓主要體驗、街區觀察與休息時間彼此銜接。</p>',
        '<figure class="table"><table><tbody><tr>',
        '<td><img src="/', source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 1, 2, '0'),
        '.jpg" alt="', source.city_name, '視角一"></td>',
        '<td><img src="/', source.image_folder, '/', source.image_folder,
        LPAD(source.cover_number + 2, 2, '0'),
        '.jpg" alt="', source.city_name, '視角二"></td>',
        '</tr></tbody></table></figure>',
        '<p>', source.route_advice, source.practical_focus,
        '兩張照片可以提醒我們，同一座城市會因觀看方向與停留時間產生完全不同的感受。出發前確認必要資訊，抵達後則允許自己偏離計畫；只要保留核心主題，行程即使臨時改動，仍然能維持完整脈絡。</p>',
        '<blockquote><p>把時間留給真正想看的內容，也把彈性留給現場發生的驚喜。</p></blockquote>'
      )
    END,

    '<hr><h3>行前規劃：先把一天拆成三個段落</h3>',
    '<p>出發前先確認核心體驗「', source.experience_title,
    '」的集合位置、報到時間、取消規則與預計結束時間，再以此向前後延伸行程。上午適合安排需要預約、排隊或集中注意力的內容；中午保留至少一小時用餐與移動；傍晚則選擇步調較慢、可依體力縮短的散步或觀景點。若同行者包含長輩、孩童或行動較慢的旅伴，應把轉乘次數與步行距離納入考量，而不只比較地圖上的直線距離。</p>',

    '<figure class="table"><table><thead><tr>',
    '<th>時段</th><th>建議安排</th><th>調整原則</th>',
    '</tr></thead><tbody>',
    '<tr><td>上午</td><td>完成主要預約與最重視的參觀內容</td><td>提早抵達，避免把兩個固定時段排得太近</td></tr>',
    '<tr><td>中午</td><td>用餐、補水並確認下午天氣與交通</td><td>優先選擇核心路線附近，不為名店大幅繞路</td></tr>',
    '<tr><td>下午</td><td>延伸周邊街區，加入一個可自由停留的地點</td><td>依人潮與體力刪減次要景點</td></tr>',
    '<tr><td>傍晚</td><td>以河岸、公園、廣場或街區散步收尾</td><td>先確認日落與回程時間，保留提早結束的彈性</td></tr>',
    '</tbody></table></figure>',

    '<h3>', source.category_label, '現場觀察重點</h3>',
    CASE source.category_id
      WHEN 1 THEN CONCAT(
        '<p>古蹟旅行不只看建築正面。抵達後可以先觀察街道寬度、石材、窗框與廣場位置，再閱讀年代說明；這些細節能幫助理解居民如何在不同時期使用空間。進入宗教或紀念場所前，請確認服裝、攝影與安檢規定。若導覽資訊很多，可只記下三個關鍵年代與一個最有感的故事，離開後再整理，會比現場急著記錄所有內容更容易形成脈絡。</p>'
      )
      WHEN 2 THEN CONCAT(
        '<p>藝文行程建議先選定一個觀看主題，例如色彩、城市生活、人物或建築，再從館藏中尋找呼應作品。每看完一個展區就短暫休息，避免後半段因資訊疲勞而只剩拍照。若展館提供語音導覽，可挑重點作品使用；若遇到特展額滿，則把常設展、建築空間與周邊藝術街區組成替代路線，仍能保留完整的藝文主題。</p>'
      )
      WHEN 3 THEN CONCAT(
        '<p>美食探索可從市場、日常餐館與一道代表料理三個層次進行。點餐前先理解份量、供餐時段與服務費方式，對乳製品、堅果、海鮮或酒精有顧慮時，應直接向店家確認。不要把每餐都排成熱門名店，穿插一間社區小店或市場攤位，更能比較旅遊區與居民日常的味道、價格及用餐節奏。</p>'
      )
      WHEN 4 THEN CONCAT(
        '<p>戶外行程需同時確認溫度、降雨、風勢、路面與日落，而不是只看晴雨圖示。出發時攜帶飲水、防曬、簡易雨具與離線地圖，並把折返時間寫進計畫。若路線比預期濕滑、炎熱或擁擠，就縮短距離或改走大眾運輸可達的公園與河岸；完成安全、舒適的半段路線，遠比勉強走完全程更值得。</p>'
      )
      WHEN 5 THEN CONCAT(
        '<p>旅拍前先選擇一種主要氛圍，並準備兩到三個動作簡單、步行距離相近的場景。清晨適合乾淨街景與柔和光線，傍晚則要預留光線快速變化的時間。拍攝時留意居民出入口、商店營業與他人肖像權，不長時間占用橋面或狹窄通道；遇到人潮時可改拍局部、背影與環境互動畫面。</p>'
      )
      ELSE CONCAT(
        '<p>夜間活動先確認年齡限制、服裝規範、入場證件、寄物方式與最後入場時間。行前把住宿地址、回程路線和備用叫車方式存進手機，同行者也應知道集合點。飲酒以能清楚判斷環境為原則，離開主要街區時避免單獨走入昏暗小巷；若演出延遲或末班車時間改變，應優先採用事先準備的回程方案。</p>'
      )
    END,

    '<h3>', source.city_name, '移動與節奏提醒</h3>',
    CASE source.city_order
      WHEN 1 THEN '<p>倫敦範圍廣、轉乘距離容易被低估，排程時以同一地鐵區域或同一側河岸為單位。尖峰時段月台與車廂較擁擠，跨區行程應多留二十至三十分鐘；步行穿越大型車站時，也要把站內移動算進時間。</p>'
      WHEN 2 THEN '<p>巴黎適合把地鐵與步行交替使用。相鄰景點看似接近，但石板路、河岸階梯與大型路口都會增加體力消耗；每天選一至兩個相鄰街區深入走訪，比頻繁橫跨左右岸更從容。</p>'
      WHEN 3 THEN '<p>阿姆斯特丹市中心適合步行與電車，但穿越單車道前必須再次確認來車。運河橋面與老城道路可能不平，攜帶大型行李時應避開複雜步行轉乘；熱門區域可安排清晨造訪，午後移往住宅街區或公園。</p>'
      WHEN 4 THEN '<p>巴塞隆納街廓規則但部分景點位於坡地，不能只依公里數判斷難度。白天較熱時可把戶外路線拆成早晚兩段，中間安排室內參觀與午休；在人潮密集的交通節點，隨身物品應放在視線可及處。</p>'
      WHEN 5 THEN '<p>慕尼黑舊城可步行串聯，較遠的公園、宮殿與場館則適合搭乘地鐵或電車。遇到大型活動時，車站與餐廳會比平日擁擠，建議提早確認替代站點，並讓午餐與晚餐時間稍微避開主要人潮。</p>'
      ELSE '<p>威尼斯以步行與水上交通為主，橋梁、階梯和狹窄巷道會讓實際移動時間高於地圖估算。不要在轉船或預約前安排過緊的路線；遇到迷路時先回到廣場、運河或主要指標，再重新確認方向。</p>'
    END,

    '<h3>雨天與臨時變動備案</h3>',
    '<p>準備備案時，不需要重新規劃另一套完整行程，只要為核心體驗附近找一個室內地點、一段有遮蔽的移動方式，以及一個可以隨時取消的休息選項。若遇到臨時閉館、交通中斷或天候惡化，先保留已預約且無法退款的項目，再依距離刪減其他內容。每次調整後都重新確認回程，不讓單一景點的變動一路壓縮後續時間。</p>',

    '<h3>出發前最後檢查</h3>',
    '<ul>',
    '<li>下載票券、集合資訊、住宿地址與必要的離線地圖。</li>',
    '<li>確認營業日、預約時段、交通異動及當地最新公告。</li>',
    '<li>依天氣準備飲水、雨具、防曬、行動電源與合適鞋子。</li>',
    '<li>將必去項目控制在一至兩個，其餘景點標記為可彈性刪減。</li>',
    '<li>每天保留至少一段沒有預約的時間，用來休息或回應現場驚喜。</li>',
    '</ul>',
    '<blockquote><p>一篇攻略的價值，不是替你決定每一步，而是讓你知道哪些資訊要先確認、哪些選擇可以留到現場。</p></blockquote>'
  ) AS content,

  CONCAT(
    source.city_name,
    '｜',
    source.category_label,
    '官方編輯指南，以「',
    source.experience_title,
    '」為核心，整理路線節奏、觀看重點與行前準備。'
  ) AS excerpt,

  CONCAT(
    '/',
    source.image_folder,
    '/',
    source.image_folder,
    LPAD(source.cover_number, 2, '0'),
    '.jpg'
  ) AS cover_image,

  CONCAT(
    '/',
    source.image_folder,
    '/',
    source.image_folder,
    LPAD(source.cover_number + 1, 2, '0'),
    '.jpg'
  ) AS content_image,

  'published' AS status,

  TIMESTAMPADD(
    DAY,
    -source.publish_order,
    '2026-07-27 18:00:00'
  ) AS published_at,

  TIMESTAMPADD(
    DAY,
    -source.publish_order,
    '2026-07-27 18:00:00'
  ) AS updated_at,

  TIMESTAMPADD(
    DAY,
    -source.publish_order,
    '2026-07-27 15:00:00'
  ) AS created_at,

  admin_member.id AS author_id,
  source.category_id,
  NULL AS order_item_id,
  source.experience_id,
  NULL AS review_note

FROM article_source AS source
INNER JOIN `member` AS admin_member
  ON admin_member.id = 102
  AND admin_member.role = '管理者'
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `content` = VALUES(`content`),
  `excerpt` = VALUES(`excerpt`),
  `cover_image` = VALUES(`cover_image`),
  `content_image` = VALUES(`content_image`),
  `status` = VALUES(`status`),
  `published_at` = VALUES(`published_at`),
  `updated_at` = VALUES(`updated_at`),
  `created_at` = VALUES(`created_at`),
  `author_id` = VALUES(`author_id`),
  `category_id` = VALUES(`category_id`),
  `experience_id` = VALUES(`experience_id`),
  `review_note` = VALUES(`review_note`);

COMMIT;

-- 驗證應為 72 篇。
SELECT COUNT(*) AS official_article_count
FROM `posts`
WHERE `slug` LIKE 'official-%-category-%';

-- 驗證每個城市／類型應各有 2 篇。
SELECT
  CASE
    WHEN e.city = '巴賽隆納' THEN '巴塞隆納'
    ELSE e.city
  END AS city,
  ec.category_name,
  COUNT(*) AS article_count
FROM `posts` AS p
INNER JOIN `experiences` AS e
  ON e.id = p.experience_id
INNER JOIN `experience_categories` AS ec
  ON ec.id = p.category_id
WHERE p.slug LIKE 'official-%-category-%'
GROUP BY
  CASE
    WHEN e.city = '巴賽隆納' THEN '巴塞隆納'
    ELSE e.city
  END,
  ec.id,
  ec.category_name
ORDER BY city, ec.id;

-- 驗證最新 12 篇應依序輪替六個城市，每個城市各出現 2 次。
SELECT
  p.slug,
  CASE
    WHEN e.city = '巴賽隆納' THEN '巴塞隆納'
    ELSE e.city
  END AS city,
  p.published_at
FROM `posts` AS p
INNER JOIN `experiences` AS e
  ON e.id = p.experience_id
WHERE p.slug LIKE 'official-%-category-%'
ORDER BY p.published_at DESC
LIMIT 12;

-- 每篇已發布文章建立 2～7 則假留言
INSERT INTO `blog_comments` (
  `post_id`,
  `member_id`,
  `content`,
  `created_at`
)
WITH
comment_slots AS (
  SELECT 1 AS slot_number
  UNION ALL SELECT 2
  UNION ALL SELECT 3
  UNION ALL SELECT 4
  UNION ALL SELECT 5
  UNION ALL SELECT 6
  UNION ALL SELECT 7
),
comment_source AS (
  SELECT
    p.id AS post_id,
    commenter.id AS member_id,

    CASE slots.slot_number
      WHEN 1 THEN CONCAT(
        '這篇「', p.title,
        '」整理得很清楚，行程節奏和注意事項都很實用，已經先收藏起來了！'
      )

      WHEN 2 THEN CONCAT(
        '最近正在規劃相關行程，剛好看到「', p.title,
        '」。文章提到要預留交通、排隊和休息時間，這點真的很容易忽略。'
      )

      WHEN 3 THEN CONCAT(
        '我之前也走過類似路線，實際花費的時間比地圖看起來更久。建議大家一定要穿好走的鞋，行程不要安排得太緊。'
      )

      WHEN 4 THEN CONCAT(
        '很喜歡「', p.title,
        '」裡面的雨天備案，不需要取消整天，只要保留主要行程再調整附近景點，帶家人旅行時很實用。'
      )

      WHEN 5 THEN CONCAT(
        '交通和步行時間的提醒很有幫助。想請問如果只有半天，會建議保留主要體驗，還是以附近街區散步為主呢？'
      )

      WHEN 6 THEN CONCAT(
        '文章用上午、中午、下午和傍晚拆分行程，讀起來比單純列出景點更容易執行，出發前知道該注意什麼真的差很多。'
      )

      ELSE CONCAT(
        '已經把「', p.title,
        '」分享給同行朋友了！我們很需要這種可以臨時刪減、又不會破壞整體行程的規劃方式。'
      )
    END AS content,

    TIMESTAMPADD(
      HOUR,
      slots.slot_number * 2,
      COALESCE(p.published_at, p.created_at)
    ) AS created_at

  FROM `posts` AS p

  CROSS JOIN comment_slots AS slots

  INNER JOIN `member` AS commenter
    ON commenter.id =
      1 + MOD(
        CRC32(p.slug) + slots.slot_number * 7,
        60
      )
    AND commenter.role = '會員'

  WHERE p.status = 'published'
    AND slots.slot_number <=
      2 + MOD(
        CRC32(CONCAT(p.slug, '-comment-count')),
        6
      )
)

SELECT
  source.post_id,
  source.member_id,
  source.content,
  source.created_at
FROM comment_source AS source

WHERE NOT EXISTS (
  SELECT 1
  FROM `blog_comments` AS existing_comment
  WHERE existing_comment.post_id = source.post_id
    AND existing_comment.member_id = source.member_id
    AND existing_comment.content = source.content
);


-- --------------------------------------------------------
-- Seed data for `experience_images`
-- 100 個體驗 × 每個體驗 5 張圖片 = 500 筆

ALTER TABLE experience_images AUTO_INCREMENT = 1;

INSERT INTO experience_images (
  experience_id,
  image_url,
  is_primary,
  sort_order,
  created_at
)
WITH RECURSIVE experience_numbers AS (
  SELECT 1 AS experience_id

  UNION ALL

  SELECT experience_id + 1
  FROM experience_numbers
  WHERE experience_id < 100
),

image_numbers AS (
  SELECT 1 AS image_number

  UNION ALL

  SELECT image_number + 1
  FROM image_numbers
  WHERE image_number < 5
)

SELECT
  e.experience_id,

  CONCAT(
    '/images/experiences/exp-',
    e.experience_id,
    '/',
    i.image_number,
    '.jpg'
  ) AS image_url,

  CASE
    WHEN i.image_number = 1 THEN 1
    ELSE 0
  END AS is_primary,

  i.image_number AS sort_order,

  NOW() AS created_at

FROM experience_numbers e
CROSS JOIN image_numbers i
ORDER BY e.experience_id, i.image_number;

